sp_theme.css_variables:
/* ===================================================== */
/* MOVIE EXPLORER – GLOBAL THEME OVERRIDE              */
/* TMDB Inspired Design                                */
/* ===================================================== */

/* ====== Theme Variables ====== */
:root {				/* globalne premenne */
  /* Brand Colors */
  --primary-color: #01B4E4;
  --secondary-color: #01D277;
  --success-color: #90CEA1;
  --warning-color: #F5C518;
  --danger-color: #D9534F;

  /* Backgrounds */
  /*--body-bg: #0D253F; */
  /*--sp-homepage-bg: #0D253F;*/
  --panel-bg: #081C2F;
  --footer-bg: #081C2F;

  /* Text */
  --text-color: #FFFFFF;
  --text-muted: rgba(255, 255, 255, 0.7);
  --link-color: #01B4E4;

  /* Navbar */
  --navbar-bg: #032541;
  --navbar-link-color: rgba(255, 255, 255, 0.8);
  --navbar-link-hover-color: #FFFFFF;

  /* Buttons */
  --btn-bg: #01B4E4;
  --btn-color: #FFFFFF;

  /* Panels / Cards */
  --panel-radius: 6px;

  /* Typography */
  --font-size-base: 16px;
  --headings-color: #FFFFFF;
  --tagline-color: rgba(255, 255, 255, 0.7);

  /* Focus outline for accessibility */
  --focus-outline-color: #01B4E4;
}

/* ==================================== */
/* CSS z Widgetu ME Header              */
/* ==================================== */
.me-header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background-color: var(--navbar-bg); /* z theme */
  color: var(--text-color);           /* z theme */
  font-family: Arial, sans-serif;     /* môžeš použiť z theme, ak máš premennú */
}

.me-header-left img {
  height: 50px;
}

.me-header-center nav a {
  margin: 0 15px;
  color: var(--navbar-link-color); /* z theme */
  text-decoration: none;
  font-weight: bold;
}

.me-header-center nav a:hover,
.me-header-center nav a.active {
  color: var(--navbar-link-hover-color); /* z theme */
  text-decoration: underline;
}

/* Dropdown */
.dropdown {
  display: inline-block;
  position: relative;
}

.dropdown-content {
  display: none;
  position: absolute;
  background-color: var(--navbar-bg);
  min-width: 120px;
  z-index: 1;
}

.dropdown:hover .dropdown-content {
  display: block;
}

.dropdown-content a {
  display: block;
  padding: 5px 10px;
  color: var(--text-color);
  text-decoration: none;
}

.dropdown-content a:hover {
  background-color: var(--success-color); /* z theme */
}

/* Search input + button */
.me-header-right input.me-search-input {
  padding: 5px 10px;
  border-radius: 4px;
  border: none;
  margin-right: 5px;
}

.me-header-right button.me-search-btn {
  padding: 5px 10px;
  background-color: var(--btn-bg);   /* z theme */
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
  color: var(--btn-color);           /* z theme */
}

.me-header-right button.me-search-btn:hover {
  background-color: var(--success-color); /* z theme */
}

.me-header-container {
  position: sticky; /* alebo fixed */
  top: 0;
  left: 0;
  width: 100%;
  z-index: 9999; /* musí byť vyššie ako všetky elementy hero/poster */
  background-color: var(--navbar-bg); /* aby bol krytý podklad */
}

/*farba pisma v header search*/
.me-header-right .me-search-input {
  width: 220px;
  padding: 6px 10px;
  border-radius: 4px;
  border: 1px solid #ccc;
  background: #ffffff;
  color: #111111;
  caret-color: #111111;
  outline: none;
}

.me-header-right .me-search-input::placeholder {
  color: #777777;
  opacity: 1;
}

.me-header-right .me-search-input:focus {
  border-color: #01B4E4;
  box-shadow: 0 0 0 2px rgba(1, 180, 228, 0.2);
}
